/**
 * Multi select is a component that allows users to select multiple options from a list.
 * It is a custom component built with a combination of the `Menu` and `MenuItem` Living Design components.
 *
 *
 * ### Content
 *
 * - Multi select is a controlled component i.e., the state is controlled by the `value` prop and `onChange` callback passed from the parent component.
 * - Render the list of options by using the `options` prop. The `options` prop accepts an array of strings OR an array of objects with a `key` and `label`. See example below. If objects are passed, the `key` values will be used as the `onChange` callback's values.
 * - Set the list of pre-selected `options` using the `value` prop. An array of strings can be passed. If objects are passed to options, the `value` prop expects values that match the `key` values of the options.
 * - A custom trigger for the menu can be passed using the menuTrigger prop and its respective ref to the menuTriggerRef prop.
 * - A maximum height along with vertical scrolling can be set using the maxMenuHeight prop.
 *
 * ### Usage
 *
 * ```tsx
 *
 * import { MultiSelect } from '@walmart-dataventures/shared-components';
 *
 * const options = ['January', 'February', 'March'];
 * const menuTriggerRef = useRef(null);
 *
 * <MultiSelect
 *   label="Select options"
 *   options={options}
 *   onChange={(selected: string[]) => console.log(selected)}
 *   menuTrigger={
 *      <Chip ref={menuTriggerRef} UNSAFE_className={isPlaceholder ? styles.placeholderLabel : styles.label}>
 *         {displayText}
 *      </Chip>}
 *   menuTriggerRef={menuTriggerRef}
 *   value={['January']}
 * />
 *
 * ```
 *
 * OR
 *
 * ```tsx
 *
 * import { MultiSelect } from '@walmart-dataventures/shared-components';
 *
 * const options = [
 *  { key: 'jan', label: 'January' }
 *  { key: 'feb', label: 'February' }
 *  { key: 'mar', label: 'March' }
 * ];
 *
 * const menuTriggerRef = useRef(null);
 *
 * <MultiSelect
 *   label="Select an option"
 *   options={options}
 *   onChange={(selected: string[]) => console.log(selected)}
 *   menuTrigger={
 *      <Chip ref={menuTriggerRef} UNSAFE_className={isPlaceholder ? styles.placeholderLabel : styles.label}>
 *         {displayText}
 *      </Chip>}
 *   menuTriggerRef={menuTriggerRef}
 *   value={['jan', 'feb']}
 * />
 *
 * ```
 *
 * ### Menu Height
 * The MenuList components provides maxMenuHeight prop for menu to enable scrolling with max height provided to the prop.
 *
 * ```tsx
 *
 * import { MultiSelect } from '@walmart-dataventures/shared-components';
 *
 * const options = [
 *  { key: 'jan', label: 'January' }
 *  { key: 'feb', label: 'February' }
 *  { key: 'mar', label: 'March' }
 * ];
 * const menuTriggerRef = useRef(null);
 *
 * <MultiSelect
 *   label="Select an option"
 *   options={options}
 *   onChange={(selected: string[]) => console.log(selected)}
 *   maxMenuHeight='5rem'
 *   menuTrigger={
 *      <Chip ref={menuTriggerRef} UNSAFE_className={isPlaceholder ? styles.placeholderLabel : styles.label}>
 *         {displayText}
 *      </Chip>}
 *   menuTriggerRef={menuTriggerRef}
 *   value={['jan', 'feb']}
 * />
 *
 * ```
 *
 * ### Search Option
 *
 * Search can be enabled within the menu by setting `isSearchEnabled` to true
 * Is search is enabled, `searchOptions` should be passed to activate the state of the search bar.
 * Filtering logic should be handled on the parent component level
 *
 * ```tsx
 * import { MultiSelect } from '@walmart-dataventures/shared-components';
 *
 * const options = [
 *  { key: 'jan', label: 'January' }
 *  { key: 'feb', label: 'February' }
 *  { key: 'mar', label: 'March' }
 * ];
 * const menuTriggerRef = useRef(null);
 *
 *  <MultiSelect
 *   label="Select an option"
 *   options={options}
 *   onChange={(selected: string[]) => console.log(selected)}
 *   menuTrigger={
 *      <Chip ref={menuTriggerRef} UNSAFE_className={isPlaceholder ? styles.placeholderLabel : styles.label}>
 *         {displayText}
 *      </Chip>}
 *   menuTriggerRef={menuTriggerRef}
 *   value={['jan', 'feb']}
 *   isSearchEnabled={true}
 *   searchOptions={{ value: searchValue, setValue: setSearchValue }}
 * />
 * ```
 *
 * ### Disable menu options
 *
 * Individual menu options can be disabled by passing an optional `disabled` prop.
 * The `disabled` prop should be passed as part of the object in the options array passed to the `LuminateMultiSelect` component.
 *
 * ```tsx
 * import { MultiSelect } from '@walmart-dataventures/shared-components';
 *
 * const options = [
 *  { key: 'jan', label: 'January', disabled: true  }
 *  { key: 'feb', label: 'February' }
 *  { key: 'mar', label: 'March' }
 * ];
 * const menuTriggerRef = useRef(null);
 *
 *  <MultiSelect
 *   label="Select an option"
 *   options={options}
 *   onChange={(selected: string[]) => console.log(selected)}
 *   menuTrigger={
 *      <Chip ref={menuTriggerRef} UNSAFE_className={isPlaceholder ? styles.placeholderLabel : styles.label}>
 *         {displayText}
 *      </Chip>}
 *   menuTriggerRef={menuTriggerRef}
 *   value={['jan', 'feb']}
 * />
 * ```
 * */
